/**
 * Storage manager for staged changesets using YAML format
 */

card.source:
export class StagedChangesetStorage {
  private changesetsDir: string;

  constructor(rootPath: string) {
    // Store changesets in documentation-robotics/changesets/ directory
    this.changesetsDir = path.join(rootPath, "documentation-robotics", "changesets");
  }

  /**
   * Create a new staged changeset directory structure
   */
  async create(
    id: string,
    name: string,
    description: string | undefined,
    baseSnapshot: string
  ): Promise<Changeset> {
    const now = new Date().toISOString();
    const sanitizedId = this.sanitizeId(id);
    const changesetPath = path.join(this.changesetsDir, sanitizedId);

    // Create directory structure
    await ensureDir(changesetPath);

    // Create metadata
    const metadata: Omit<StagedChangesetData, "changes"> = {
      id: sanitizedId,
      name,
      description,
      created: now,
      modified: now,
      status: "staged",
      baseSnapshot,
      stats: {
        additions: 0,
        modifications: 0,
        deletions: 0,
      },
    };

    // Write metadata.yaml
    await writeFile(path.join(changesetPath, "metadata.yaml"), yaml.stringify(metadata), "utf-8");

    // Write empty changes.yaml
    await writeFile(path.join(changesetPath, "changes.yaml"), yaml.stringify([]), "utf-8");

    // Return constructed changeset object
    return new Changeset({
      id: sanitizedId,
      name,
      description,
      created: now,
      modified: now,
      status: "staged",
      baseSnapshot,
      changes: [],
      stats: metadata.stats,
    });
  }

  /**
   * Load a staged changeset from YAML files
   */
  async load(id: string): Promise<Changeset | null> {
    const sanitizedId = this.sanitizeId(id);
    const changesetPath = path.join(this.changesetsDir, sanitizedId);
    const metadataPath = path.join(changesetPath, "metadata.yaml");
    const changesPath = path.join(changesetPath, "changes.yaml");

    // Check if changeset directory exists
    if (!(await fileExists(changesetPath))) {
      return null; // Changeset doesn't exist - this is OK
    }

    // Changeset directory exists - files SHOULD be present
    const metadataExists = await fileExists(metadataPath);
    const changesExists = await fileExists(changesPath);

    if (!metadataExists || !changesExists) {
      // Changeset directory exists but required files are missing - this is corruption
      throw new Error(
        `Changeset '${id}' is corrupted (missing ${!metadataExists ? "metadata.yaml" : "changes.yaml"}). ` +
          `Location: ${changesetPath}\n` +
          `This may indicate disk failure or incomplete write. Check disk health and restore from backup if available.`
      );
    }

    try {
      // Load metadata
      const metadataContent = await readFile(metadataPath, "utf-8");
      const metadata = yaml.parse(metadataContent);

      // Load changes
      const changesContent = await readFile(changesPath, "utf-8");
      const changes = yaml.parse(changesContent) || [];

      // Construct changeset object
      const data: StagedChangesetData = {
        id: metadata.id,
        name: metadata.name,
        description: metadata.description,
        created: metadata.created,
        modified: metadata.modified,
        status: metadata.status,
        baseSnapshot: metadata.baseSnapshot,
        changes: changes as StagedChange[],
        stats: metadata.stats || { additions: 0, modifications: 0, deletions: 0 },
      };

      return Changeset.fromJSON(data);
    } catch (error) {
      // YAML parsing or file read error - provide detailed guidance
      throw new Error(
        `Failed to load changeset '${id}': YAML parsing failed.\n` +
          `Error: ${getErrorMessage(error)}\n` +
          `Location: ${metadataPath}\n` +
          `This indicates file corruption. Try:\n` +
          `  1. Validate YAML syntax with: yamllint ${metadataPath}\n` +
          `  2. Restore from backup if available\n` +
          `  3. Manually edit to fix syntax errors`

/**
 * Chat Logger Utility
 *
 * Provides universal logging for all chat messages and commands.
 * Stores logs in .dr/chat/sessions/ with one file per session.
 * Filenames include both timestamp and session ID for chronological ordering.
 *
 * Log format:
 * - Session file: .dr/chat/sessions/{timestamp}_{sessionId}.log
 * - Timestamp comes first for natural sorting (most recent first)
 * - Timestamp format: ISO 8601 with colons replaced by underscores for filesystem compatibility
 * - Each entry contains: timestamp, type (message/command/error), role, content
 */

import { mkdir, writeFile, appendFile, readdir, readFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

/**
 * Helper to append content to file with automatic retry on ENOENT
 *
 * When appending to a file, a race condition can occur where the file
 * or directory is deleted between the initial write and the append.
 * This helper handles ENOENT by recreating the directory and file with header.
 *
 * @param filePath Path to file to append to
 * @param content Content to append
 * @param onRetry Callback to prepare file (e.g., write header) before retry
 * @throws Error if append fails for non-ENOENT reasons
 */
async function appendWithRetry(
  filePath: string,
  content: string,
  onRetry?: () => Promise<void>
): Promise<void> {
  try {
    await appendFile(filePath, content, "utf-8");
  } catch (appendError) {
    const errno = (appendError as NodeJS.ErrnoException).code;
    if (errno === "ENOENT") {
      // File doesn't exist - race condition where directory/file was deleted
      // Call retry callback (e.g., to recreate directory and file with header)
      if (onRetry) {
        await onRetry();
      }
      // Retry the append
      try {
        await appendFile(filePath, content, "utf-8");
      } catch (retryError) {
        // Retry failed - this is a real problem
        console.warn("[ChatLogger] WARNING: Could not append entry to chat log (non-fatal)");
        console.warn("[ChatLogger]   Log path:", filePath);
        console.warn("[ChatLogger]   Error:", retryError);
        console.warn(
          "[ChatLogger]   The chat session will continue, but this entry was not logged."
        );
        // Intentional: Continue without logging rather than crash the entire session.
        // The chat log is best-effort; we don't want logging failures to break the user's work.
      }
    } else {
      // Rethrow non-ENOENT errors to outer handler
      throw appendError;
    }
  }
}

/**
 * Chat log entry types
 */
export type ChatLogEntryType = "message" | "command" | "error" | "event";

/**
 * A single chat log entry
 */
export interface ChatLogEntry {
  timestamp: string;
  type: ChatLogEntryType;
  role?: "user" | "assistant" | "system" | "cli";
  content: string;
  metadata?: Record<string, unknown>;
}

